 }\\r\\n\\r\\n    .carousel-slide {\\r\\n      min-width: 100%;\\r\\n      height: 500px; \\/* \\ud83d\\udd39 mesma altura do container *\\/\\r\\n      background-size: cover;\\r\\n      background-position: center;\\r\\n    }\\r\\n\\r\\n    \\/* \\ud83d\\udd39 Bot\\u00f5es de navega\\u00e7\\u00e3o *\\/\\r\\n    .carousel-button {\\r\\n      position: absolute;\\r\\n      top: 50%;\\r\\n      transform: translateY(-50%);\\r\\n      background: rgba(0,0,0,0.5);\\r\\n      border: none;\\r\\n      color: #fff;\\r\\n      font-size: 2rem;\\r\\n      padding: 0.5rem 1rem;\\r\\n      cursor: pointer;\\r\\n      border-radius: 50%;\\r\\n      z-index: 10;\\r\\n      transition: background 0.3s;\\r\\n    }\\r\\n\\r\\n    .carousel-button:hover {\\r\\n      background: rgba(0,0,0,0.8);\\r\\n    }\\r\\n\\r\\n    .carousel-button.prev {\\r\\n      left: 20px;\\r\\n    }\\r\\n\\r\\n    .carousel-button.next {\\r\\n      right: 20px;\\r\\n    }\\r\\n\\r\\n    \\/* \\ud83d\\udd39 Bolinhas indicadores *\\/\\r\\n    .carousel-dots {\\r\\n      position: absolute;\\r\\n      bottom: 15px;\\r\\n      left: 50%;\\r\\n      transform: translateX(-50%);\\r\\n      display: flex;\\r\\n      gap: 10px;\\r\\n    }\\r\\n\\r\\n    .carousel-dot {\\r\\n      width: 12px;\\r\\n      height: 12px;\\r\\n      background: rgba(255,255,255,0.6);\\r\\n      border-radius: 50%;\\r\\n      cursor: pointer;\\r\\n      transition: background 0.3s;\\r\\n    }\\r\\n\\r\\n    .carousel-dot.active {\\r\\n      background: #0072CE;\\r\\n      transform: scale(1.2);\\r\\n    }\\r\\n  <\\/style>\\r\\n<\\/head>\\r\\n<body>\\r\\n\\r\\n  <div class=\\\"carousel\\\">\\r\\n    <div class=\\\"carousel-track\\\">\\r\\n      <div class=\\\"carousel-slide\\\" style=\\\"background-image: url(\'https:\\/\\/picsum.photos\\/id\\/1018\\/1600\\/500\');\\\"><\\/div>\\r\\n      <div class=\\\"carousel-slide\\\" style=\\\"background-image: url(\'https:\\/\\/picsum.photos\\/id\\/1015\\/1600\\/500\');\\\"><\\/div>\\r\\n      <div class=\\\"carousel-slide\\\" style=\\\"background-image: url(\'https:\\/\\/picsum.photos\\/id\\/1019\\/1600\\/500\');\\\"><\\/div>\\r\\n    <\\/div>\\r\\n\\r\\n    <!-- Bot\\u00f5es -->\\r\\n    <button class=\\\"carousel-button prev\\\">&#10094;<\\/button>\\r\\n    <button class=\\\"carousel-button next\\\">&#10095;<\\/button>\\r\\n\\r\\n    <!-- Bolinhas -->\\r\\n    <div class=\\\"carousel-dots\\\"><\\/div>\\r\\n  <\\/div>\\r\\n\\r\\n  <script>\\r\\n    const track = document.querySelector(\'.carousel-track\');\\r\\n    const slides = Array.from(track.children);\\r\\n    const nextButton = document.querySelector(\'.carousel-button.next\');\\r\\n    const prevButton = document.querySelector(\'.carousel-button.prev\');\\r\\n    const dotsNav = document.querySelector(\'.carousel-dots\');\\r\\n\\r\\n    let currentIndex = 0;\\r\\n\\r\\n    \\/\\/ Criar bolinhas dinamicamente\\r\\n    slides.forEach((_, i) => {\\r\\n      const dot = document.createElement(\'div\');\\r\\n      dot.classList.add(\'carousel-dot\');\\r\\n      if (i === 0) dot.classList.add(\'active\');\\r\\n      dot.addEventListener(\'click\', () => goToSlide(i));\\r\\n      dotsNav.appendChild(dot);\\r\\n    });\\r\\n\\r\\n    const dots = Array.from(dotsNav.children);\\r\\n\\r\\n    function updateSlidePosition() {\\r\\n      track.style.transform = `translateX(-${currentIndex * 100}%)`;\\r\\n      dots.forEach(dot => dot.classList.remove(\'active\'));\\r\\n      dots[currentIndex].classList.add(\'active\');\\r\\n    }\\r\\n\\r\\n    function goToSlide(index) {\\r\\n      currentIndex = index;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function nextSlide() {\\r\\n      currentIndex = (currentIndex + 1) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function prevSlide() {\\r\\n      currentIndex = (currentIndex - 1 + slides.length) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    nextButton.addEventListener(\'click\', nextSlide);\\r\\n    prevButton.addEventListener(\'click\', prevSlide);\\r\\n\\r\\n    \\/\\/ Auto play (opcional)\\r\\n    setInterval(nextSlide, 5000);\\r\\n  <\\/script>\\r\\n\\r\\n<\\/body>\\r\\n<\\/html>\\r\\n\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"5bf0d5c\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":30,\"column\":\"30\",\"row\":\"0\"},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"100\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"be69dd9\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"}},\"elements\":[{\"id\":\"4a48212\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/fisica\\/wp-content\\/uploads\\/2025\\/07\\/fisica-quantica-og.png\",\"id\":91,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"align\":\"left\",\"image_border_radius\":{\"unit\":\"px\",\"top\":\"10\",\"right\":\"10\",\"bottom\":\"10\",\"left\":\"10\",\"isLinked\":true}},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":true},{\"id\":\"ff258c3\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"}},\"elements\":[{\"id\":\"99515f1\",\"elType\":\"widget\",\"settings\":{\"title\":\"\\ud83d\\udd2c O Mundo Invis\\u00edvel da F\\u00edsica Qu\\u00e2ntica\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":26,\"sizes\":[]},\"typography_font_weight\":\"bold\",\"__globals__\":{\"typography_typography\":\"\"}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"35ef759\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p data-start=\\\"161\\\" data-end=\\\"673\\\">A F\\u00edsica Qu\\u00e2ntica \\u00e9 o ramo da ci\\u00eancia que estuda o comportamento da mat\\u00e9ria e da energia e