ick\', nextSlide);\\r\\n    prevButton.addEventListener(\'click\', prevSlide);\\r\\n\\r\\n    \\/\\/ Auto play (opcional)\\r\\n    setInterval(nextSlide, 5000);\\r\\n  <\\/script>\\r\\n\\r\\n<\\/body>\\r\\n<\\/html>\\r\\n\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"653a035\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\"},\"elements\":[{\"id\":\"effc71e\",\"elType\":\"widget\",\"settings\":{\"title\":\"Eventos\",\"header_size\":\"h1\",\"align\":\"center\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":48,\"sizes\":[]},\"typography_font_weight\":\"bold\"},\"elements\":[],\"widgetType\":\"heading\"}],\"isInner\":false},{\"id\":\"e0a170a\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":40,\"column\":\"40\",\"row\":\"0\"},\"margin\":{\"unit\":\"px\",\"top\":\"100\",\"right\":\"0\",\"bottom\":\"100\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"e2597eb\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"}},\"elements\":[{\"id\":\"23cb185\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/fisica\\/wp-content\\/uploads\\/2025\\/09\\/WhatsApp-Image-2025-08-25-at-15.23.48.jpg\",\"id\":425,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"link_to\":\"file\",\"open_lightbox\":\"yes\",\"_background_background\":\"classic\",\"__globals__\":{\"_background_color\":\"\"}},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":true},{\"id\":\"21b6bf9\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"}},\"elements\":[{\"id\":\"c66aaa3\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/fisica\\/wp-content\\/uploads\\/2025\\/09\\/WhatsApp-Image-