;\\r\\n      background: #f4f4f4;\\r\\n    }\\r\\n\\r\\n    .carousel {\\r\\n      position: relative;\\r\\n      width: 100%;\\r\\n      height: 500px; \\/* \\ud83d\\udd39 Ajuste a altura aqui *\\/\\r\\n      overflow: hidden;\\r\\n    }\\r\\n\\r\\n    .carousel-track {\\r\\n      display: flex;\\r\\n      transition: transform 0.5s ease-in-out;\\r\\n      height: 100%;\\r\\n    }\\r\\n\\r\\n    .carousel-slide {\\r\\n      min-width: 100%;\\r\\n      height: 100%;\\r\\n      background-size: cover;      \\/* \\ud83d\\udd39 Preenche sempre todo o container *\\/\\r\\n      background-position: center; \\/* \\ud83d\\udd39 Centraliza *\\/\\r\\n      background-repeat: no-repeat;\\/* \\ud83d\\udd39 Evita repeti\\u00e7\\u00e3o *\\/\\r\\n    }\\r\\n\\r\\n    \\/* \\ud83d\\udd39 Bot\\u00f5es de navega\\u00e7\\u00e3o *\\/\\r\\n    .carousel-button {\\r\\n      position: absolute;\\r\\n      top: 50%;\\r\\n      transform: translateY(-50%);\\r\\n      background: rgba(0,0,0,0.5);\\r\\n      border: none;\\r\\n      color: #fff;\\r\\n      font-size: 2rem;\\r\\n      padding: 0.5rem 1rem;\\r\\n      cursor: pointer;\\r\\n      border-radius: 50%;\\r\\n      z-index: 10;\\r\\n      transition: background 0.3s;\\r\\n    }\\r\\n\\r\\n    .carousel-button:hover {\\r\\n      background: rgba(0,0,0,0.8);\\r\\n    }\\r\\n\\r\\n    .carousel-button.prev { left: 20px; }\\r\\n    .carousel-button.next { right: 20px; }\\r\\n\\r\\n    \\/* \\ud83d\\udd39 Bolinhas indicadores *\\/\\r\\n    .carousel-dots {\\r\\n      position: absolute;\\r\\n      bottom: 15px;\\r\\n      left: 50%;\\r\\n      transform: translateX(-50%);\\r\\n      display: flex;\\r\\n      gap: 10px;\\r\\n    }\\r\\n\\r\\n    .carousel-dot {\\r\\n      width: 12px;\\r\\n      height: 12px;\\r\\n      background: rgba(255,255,255,0.6);\\r\\n      border-radius: 50%;\\r\\n      cursor: pointer;\\r\\n      transition: all 0.3s;\\r\\n    }\\r\\n\\r\\n    .carousel-dot.active {\\r\\n      background: #0072CE;\\r\\n      tra