e\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_justify_content\":\"center\",\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"100\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"81001cd\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[icones_servicos_uerj]\"},\"elements\":[],\"widgetType\":\"shortcode\"}],\"isInner\":false},{\"id\":\"71fb9cf\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"flex_gap\":{\"column\":\"20\",\"row\":\"20\",\"isLinked\":true,\"unit\":\"px\",\"size\":20}},\"elements\":[{\"id\":\"212f14a\",\"elType\":\"widget\",\"settings\":{\"title\":\"Pesquisa e Desenvolvimento\",\"header_size\":\"h1\",\"align\":\"center\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":40,\"sizes\":[]},\"typography_font_weight\":\"bold\",\"title_color\":\"#003BB1\"},\"elements\":[],\"widgetType\":\"heading\"}],\"isInner\":false},{\"id\":\"d2ecde4\",\"elType\":\"container\",\"settings\":[],\"elements\":[{\"id\":\"4a9b85c\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[quadrados_servicos_modal]\"},\"elements\":[],\"widgetType\":\"shortcode\"}],\"isInner\":false}]'),(3647,295,'_elementor_edit_mode','builder'),(3648,295,'_elementor_template_type','wp-page'),(3649,295,'_elementor_version','3.32.1'),(3686,521,'_elementor_edit_mode','builder'),(3687,521,'_elementor_template_type','wp-page'),(3688,521,'_elementor_version','3.32.1'),(3691,522,'_elementor_edit_mode','builder'),(3692,522,'_elementor_template_type','wp-page'),(3693,522,'_elementor_version','3.32.1'),(3696,295,'_wp_page_template','elementor_header_footer'),(3697,295,'_elementor_data','[{\"id\":\"fisicadocenteshtmlv2\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"fisicadocenteshtmlwidgetv2\",\"elType\":\"widget\",\"settings\":{\"html\":\"<section class=\\\"fisica-docentes-page\\\" data-docentes-app>\\n  \\n  \\n  \\n    <style>\\n    .fisica-docentes-page {\\n      --fisica-doc-bg: #f5f8fc;\\n      --fisica-doc-card: #ffffff;\\n      --fisica-doc-card-soft: #edf5ff;\\n      --fisica-doc-text: #16324f;\\n      --fisica-doc-text-soft: #557089;\\n      --fisica-doc-primary: #0f4c81;\\n      --fisica-doc-primary-strong: #0b2f4a;\\n      --fisica-doc-accent: #59a8ff;\\n      --fisica-doc-border: rgba(15, 76, 129, 0.14);\\n      --fisica-doc-shadow: 0 24px 56px rgba(11, 47, 74, 0.12);\\n      --fisica-doc-shadow-soft: 0 14px 30px rgba(11, 47, 74, 0.08);\\n      max-width: 1400px;\\n      margin: 0 auto;\\n      padding: 28px 18px 70px;\\n      color: var(--fisica-doc-text);\\n      font-family: \\\"Segoe UI\\\", \\\"Helvetica Neue\\\", Arial, sans-serif;\\n    }\\n    .fisica-docentes-page * {\\n      box-sizing: border-box;\\n    }\\n    .fisica-docentes-hero {\\n      position: relative;\\n      overflow: hidden;\\n      margin-bottom: 26px;\\n      padding: clamp(28px, 5vw, 42px);\\n      border-radius: 30px;\\n      background:\\n        radial-gradient(circle at top right, rgba(89, 168, 255, 0.32), transparent 28%),\\n        linear-gradient(135deg, #0b2f4a 0%, #0f4c81 58%, #1f6fb4 100%);\\n      box-shadow: 0 26px 58px rgba(11, 47, 74, 0.22);\\n      color: #ffffff;\\n    }\\n    .fisica-docentes-hero::after {\\n      content: \\\"\\\";\\n      position: absolute;\\n      inset: auto -70px -90px auto;\\n      width: 260px;\\n      height: 260px;\\n      border-radius: 50%;\\n      background: radial-gradient(circle, rgba(255, 255, 255, 0.2), rgba(255, 255, 255, 0));\\n      pointer-events: none;\\n    }\\n    .fisica-docentes-eyebrow {\\n      display: inline-flex;\\n      align-items: center;\\n      gap: 8px;\\n      padding: 8px 14px;\\n      border-radius: 999px;\\n      background: rgba(255, 255, 255, 0.14);\\n      font-size: 12px;\\n      font-weight: 800;\\n      letter-spacing: 0.12em;\\n      text-transform: uppercase;\\n    }\\n    .fisica-docentes-hero h1 {\\n      margin: 16px 0 12px;\\n      max-width: 14ch;\\n      font-size: clamp(30px, 4.3vw, 50px);\\n      line-height: 1.02;\\n      font-weight: 800;\\n      color: #ffffff;\\n    }\\n    .fisica-docentes-hero p {\\n      max-width: 74ch;\\n      margin: 0;\\n      color: rgba(255, 255, 255, 0.88);\\n      font-size: 16px;\\n      line-height: 1.75;\\n    }\\n    .fisica-docentes-overview {\\n      display: grid;\\n      grid-template-columns: minmax(0, 1.8fr) repeat(3, minmax(0, 1fr));\\n      gap: 18px;\\n      margin-bottom: 24px;\\n    }\\n    .fisica-docentes-overview__card {\\n      padding: 22px 22px 20px;\\n      border-radius: 24px;\\n      background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);\\n      border: 1px solid var(--fisica-doc-border);\\n      box-shadow: var(--fisica-doc-shadow-soft);\\n    }\\n    .fisica-docentes-overview__card strong {\\n      display: block;\\n      color: var(--fisica-doc-primary-strong);\\n      font-size: clamp(30px, 4vw, 42px);\\n      line-height: 1;\\n      font-weight: 800;\\n    }\\n    .fisica-docentes-overview__card span {\\n      display: block;\\n      margin-top: 8px;\\n      color: var(--fisica-doc-text-soft);\\n      font-size: 14px;\\n      line-height: 1.6;\\n    }\\n    .fisica-docentes-overview__card--lead {\\n      background:\\n        linear-gradient(180deg, rgba(255, 255, 255, 0.98) 0%, rgba(237, 245, 255, 0.96) 100%);\\n    }\\n    .fisica-docentes-overview__card--lead h2 {\\n      margin: 0 0 10px;\\n      color: var(--fisica-doc-primary-strong);\\n      font-size: clamp(22px, 2.6vw, 30px);\\n      line-height: 1.15;\\n      font-weight: 800;\\n    }\\n    .fisica-docentes-overview__card--lead p {\\n      margin: 0;\\n      color: var(--fisica-doc-text-soft);\\n      font-size: 15px;\\n      line-height: 1.7;\\n    }\\n    .fisica-docentes-toolbar {\\n      display: flex;\\n      flex-wrap: wrap;\\n      align-items: center;\\n      justify-content: space-between;\\n      gap: 16px;\\n      margin-bottom: 18px;\\n    }\\n    .fisica-docentes-search {\\n      display: flex;\\n      align-items: center;\\n      gap: 12px;\\n      min-width: min(100%, 460px);\\n      padding: 14px 18px;\\n      border-radius: 18px;\\n      background: #ffffff;\\n      border: 1px solid var(--fisica-doc-border);\\n      box-shadow: var(--fisica-doc-shadow-soft);\\n    }\\n    .fisica-docentes-search span {\\n      color: var(--fisica-doc-primary);\\n      font-size: 16px;\\n      font-weight: 700;\\n    }\\n    .fisica-docentes-search input {\\n      flex: 1 1 auto;\\n      min-width: 0;\\n      border: 0;\\n      outline: none;\\n      background: transparent;\\n      color: var(--fisica-doc-primary-strong);\\n      font-size: 15px;\\n    }\\n    .fisica-docentes-search input::placeholder {\\n      color: #7b90a4;\\n    }\\n    .fisica-docentes-toolbar__info {\\n      color: var(--fisica-doc-text-soft);\\n      font-size: 14px;\\n      line-height: 1.6;\\n    }\\n    .fisica-docentes-tabs {\\n      display: flex;\\n      flex-wrap: wrap;\\n      gap: 12px;\\n      margin-bottom: 20px;\\n    }\\n    .fisica-docentes-tab {\\n      display: inline-flex;\\n      align-items: center;\\n      gap: 12px;\\n      appearance: none;\\n      border: 1px solid rgba(15, 76, 129, 0.16);\\n      background: #ffffff;\\n      color: var(--fisica-doc-primary);\\n      border-radius: 18px;\\n      padding: 14px 16px;\\n      font-size: 14px;\\n      line-height: 1.3;\\n      font-weight: 800;\\n      cursor: pointer;\\n      box-shadow: var(--fisica-doc-shadow-soft);\\n      transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease, background 180ms ease, color 180ms ease;\\n    }\\n    .fisica-docentes-tab:hover,\\n    .fisica-docentes-tab:focus-visible {\\n      transform: translateY(-2px);\\n      border-color: rgba(15, 7