.textContent = String(app.querySelectorAll(\'.fisica-docentes-row\').length);\\n      };\\n\\n      const activate = (index) => {\\n        tabs.forEach((tab, tabIndex) => {\\n          const active = tabIndex === index;\\n          tab.classList.toggle(\'is-active\', active);\\n          tab.setAttribute(\'aria-selected\', active ? \'true\' : \'false\');\\n        });\\n\\n        panels.forEach((panel, panelIndex) => {\\n          const active = panelIndex === index;\\n          panel.classList.toggle(\'is-active\', active);\\n          panel.hidden = !active;\\n        });\\n\\n        filterRows();\\n      };\\n\\n      const filterRows = () => {\\n        const activePanel = app.querySelector(\'.fisica-docentes-panel.is-active\');\\n        if (!activePanel) {\\n          return;\\n        }\\n\\n        const term = (search?.value || \'\').trim().toLowerCase();\\n        const rows = Array.from(activePanel.querySelectorAll(\'.fisica-docentes-row\'));\\n        let visible = 0;\\n\\n        rows.forEach((row) => {\\n          const haystack = row.dataset.search || \'\';\\n          const match = term === \'\' || haystack.includes(term);\\n          row.hidden = !match;\\n          if (match) {\\n            visible += 1;\\n          }\\n        });\\n\\n        const empty = activePanel.querySelector(\'.fisica-docentes-empty\');\\n        if (empty) {\\n          empty.hidden = visible === 0 ? false : true;\\n        }\\n\\n        if (feedback) {\\n          if (term === \'\') {\\n            feedback.textContent = \'Consulte a rela\\u00e7\\u00e3o completa de docentes por \\u00e1rea.\';\\n          } else {\\n            feedback.textContent = visible + \' docente(s) encontrado(s) na \\u00e1rea selecionada.\';\\n          }\\n        }\\n      };\\n\\n      tabs.forEach((tab) => {\\n        tab.addEventListener(\'click\', () => activate(Number(tab.dataset.docentesTab || 0)));\\n      });\\n\\n      search?.addEventListener(\'input\', filterRows);\\n      updateTotal();\\n      activate(0);\\n    })();\\n  \\n  <\\/script>\\n<\\/section>\\n\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false}]'),(3698,523,'_elementor_edit_mode','builder'),(3699,523,'_elementor_template_type','wp-page'),(3700,523,'_elementor_version','3.32.1'),(3703,523,'_wp_page_template','elementor_header_footer'),(3704,523,'_elementor_data','[{\"id\":\"98f80bf\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"flex_align_items\":\"center\",\"margin\":{\"unit\":\"px\",\"top\":\"40\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"7c4d611\",\"elType\":\"widget\",\"settings\":{\"title\":\"Docentes do Intituto de F\\u00edsica Armando Dias Tavares\",\"align\":\"left\",\"title_color\":\"#003BB1\",\"_margin\":{\"unit\":\"px\",\"top\":\"020\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"heading\"}],\"isInner\":false},{\"id\":\"ae7c9b4\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"boxed_width\":{\"unit\":\"px\",\"size\":1439,\"sizes\":[]}},\"elements\":[{\"id\":\"0dc0c13\",\"elType\":\"widget\",\"widgetType\":\"nested-tabs\",\"settings\":{\"tabs\":[{\"tab_title\":\"Fisica Aplicada e Termodin\\u00e2mica\",\"_id\":\"d7ec645\"},{\"tab_title\":\"Eletr\\u00f4nica Qu\\u00e2ntica\",\"_id\":\"450749d\"},{\"tab_title\":\"F\\u00edsica Te\\u00f3rica\",\"_id\":\"8b1dd03\"},{\"_id\":\"89f76c8\",\"tab_title\":\"F\\u00edsica Nuclear e Altas Energias\"}],\"title_alignment\":\"center\",\"tabs_title_space_between\":{\"unit\":\"px\",\"size\":13,\"sizes\":[]},\"tabs_title_spacing\":{\"unit\":\"px\",\"size\":15,\"sizes\":[]},\"tabs_title_border_border\":\"solid\",\"tabs_title_border_color\":\"#003BB1\",\"tabs_title_background_color_hover_color\":\"#003BB1\",\"tabs_title_background_color_active_color\":\"#003BB1\",\"tabs_title_border_radius\":{\"unit\":\"px\",\"top\":\"10\",\"right\":\"10\",\"bottom\":\"10\",\"left\":\"10\",