  <!--<p>O objetivo desta reformula\\u00e7\\u00e3o \\u00e9 transmitir confian\\u00e7a, clareza e organiza\\u00e7\\u00e3o j\\u00e1 no primeiro contato com o site.<\\/p>-->\\n      <\\/div>\\n    <\\/a>\\n  <\\/div>\\n<\\/section>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"labsanchor1\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\"},\"elements\":[{\"id\":\"labshtml1\",\"elType\":\"widget\",\"settings\":{\"html\":\"<div id=\\\"laboratorios\\\"><\\/div>\"},\"elements\":[],\"widgetType\":\"html\"},{\"id\":\"labsshort1\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[icones_servicos_uerj]\"},\"elements\":[],\"widgetType\":\"shortcode\"}],\"isInner\":false},{\"id\":\"programanchor1\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\"},\"elements\":[{\"id\":\"programhtml1\",\"elType\":\"widget\",\"settings\":{\"html\":\"<div id=\\\"programas\\\"><\\/div>\"},\"elements\":[],\"widgetType\":\"html\"},{\"id\":\"programshort1\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[quadrados_servicos_link]\"},\"elements\":[],\"widgetType\":\"shortcode\"}],\"isInner\":false}]'),(6463,1087,'_elementor_edit_mode','builder'),(6469,1088,'_menu_item_type','custom'),(6470,1088,'_menu_item_menu_item_parent','24'),(6471,1088,'_menu_item_object_id','1088'),(6472,1088,'_menu_item_object','custom'),(6473,1088,'_menu_item_target',''),(6474,1088,'_menu_item_classes','a:1:{i:0;s:0:\"\";}'),(6475,1088,'_menu_item_xfn',''),(6476,1088,'_menu_item_url','#'),(6477,1089,'_menu_item_type','post_type'),(6478,1089,'_menu_item_menu_item_parent','1088'),(6479,1089,'_menu_item_object_id','1094'),(6480,1089,'_menu_item_object','page'),(6481,1089,'_menu_item_target',''),(6482,1089,'_menu_item_classes','a:1:{i:0;s:0:\"\";}'),(6483,1089,'_menu_item_xfn',''),(6484,1089,'_menu_item_url',''),(6485,1090,'_menu_item_type','custom'),(6486,1090,'_menu_item_menu_item_parent','1088'),(6487,