h: 0;n      border: 0;n      outline: none;n      background: transparent;n      color: var(--fisica-doc-primary-strong);n      font-size: 15px;n    }n    .fisica-docentes-search input::placeholder {n      color: #7b90a4;n    }n    .fisica-docentes-toolbar__info {n      color: var(--fisica-doc-text-soft);n      font-size: 14px;n      line-height: 1.6;n    }n    .fisica-docentes-tabs {n      display: flex;n      flex-wrap: wrap;n      gap: 12px;n      margin-bottom: 20px;n    }n    .fisica-docentes-tab {n      display: inline-flex;n      align-items: center;n      gap: 12px;n      appearance: none;n      border: 1px solid rgba(15, 76, 129, 0.16);n      background: #ffffff;n      color: var(--fisica-doc-primary);n      border-radius: 18px;n      padding: 14px 16px;n      font-size: 14px;n      line-height: 1.3;n      font-weight: 800;n      cursor: pointer;n      box-shadow: var(--fisica-doc-shadow-soft);n      transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease, background 180ms ease, color 180ms ease;n    }n    .fisica-docentes-tab:hover,n    .fisica-docentes-tab:focus-visible {n      transform: translateY(-2px);n      border-color: rgba(15, 76, 129, 0.34);n      outline: none;n    }n    .fisica-docentes-tab.is-active {n      background: linear-gradient(135deg, #0f4c81 0%, #1f6fb4 100%);n      color: #ffffff;n      border-color: #0f4c81;n      box-shadow: 0 20px 34px rgba(15, 76, 129, 0.22);n    }n    .fisica-docentes-tab__label {n      text-align: left;n    }n    .fisica-docentes-tab__count {n      display: inline-flex;n      align-items: center;n      justify-content: center;n      min-width: 32px;n      padding: 4px 9px;n      border-radius: 999px;n      background: rgba(15, 76, 129, 0.08);n      font-size: 12px;n      line-height: 1;n      font-weight: 800;n    }n    .fisica-docentes-tab.is-active .fisica-docentes-tab__count {n      background: rgba(255, 255, 255, 0.18);n    }n    .fisica-docentes-panel {n      display: none;n      b