:{s:4:\"time\";i:1781796880;s:5:\"fonts\";a:0:{}s:5:\"icons\";a:0:{}s:20:\"dynamic_elements_ids\";a:0:{}s:6:\"status\";s:5:\"empty\";i:0;s:0:\"\";s:3:\"css\";s:0:\"\";}'),(7808,307,'_elementor_page_assets','a:0:{}'),(7809,309,'_elementor_page_assets','a:0:{}'),(7816,1248,'_elementor_edit_mode','builder'),(7817,1248,'_elementor_template_type','wp-page'),(7818,1248,'_elementor_version','3.32.1'),(7819,1248,'_wp_page_template','elementor_header_footer'),(7820,1248,'_elementor_data','[{\"id\":\"fisicadocenteshtmlv2\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"fisicadocenteshtmlwidgetv2\",\"elType\":\"widget\",\"settings\":{\"html\":\"<?xml encoding=\"utf-8\" ?><section class=\"fisica-docentes-page\" data-docentes-app>n  <style>n    .fisica-docentes-page {n      --fisica-doc-bg: #f5f8fc;n      --fisica-doc-card: #ffffff;n      --fisica-doc-card-soft: #edf5ff;n      --fisica-doc-text: #16324f;n      --fisica-doc-text-soft: #557089;n      --fisica-doc-primary: #0f4c81;n      --fisica-doc-primary-strong: #0b2f4a;n      --fisica-doc-accent: #59a8ff;n      --fisica-doc-border: rgba(15, 76, 129, 0.14);n      --fisica-doc-shadow: 0 24px 56px rgba(11, 47, 74, 0.12);n      --fisica-doc-shadow-soft: 0 14px 30px rgba(11, 47, 74, 0.08);n      max-width: 1400px;n      margin: 0 auto;n      padding: 28px 18px 70px;n      color: var(--fisica-doc-text);n      font-family: \"Segoe UI\", \"Helvetica Neue\", Arial, sans-serif;n    }n    .fisica-docentes-page * {n      box-sizing: border-box;n    }n    .fisica-docentes-hero {n      position: relative;n      overflow: hidden;n      margin-bottom: 26px;n      padding: clamp(28px, 5vw, 42px);n      border-radius: 30px;n      background:n        radial-gradient(circle at top right, rgba(89, 168, 255, 0.32), transparent 28%),n        linear-gradient(135deg, #0b2f4a 0%, #0f4c81 58%, #1f6fb4 100%);n      box-shadow: 0 26px 58px rgba(11, 47, 74, 0.22);n      color: #ffffff;n    }n    .fisica-docentes-hero::after {n      content: \"\";n      position: absolute;n      inset: auto -70px -90px auto;n      width: 260px;n      height: 260px;n      border-radius: 50%;n      background: radial-gradient(circle, rgba(255, 255, 255, 0.2), rgba(255, 255, 255, 0));n      pointer-events: none;n    }n    .fisica-docentes-eyebrow {n      display: inline-flex;n      align-items: center;n      gap: 8px;n      padding: 8px 14px;n      border-radius: 999px;n      background: rgba(255, 255, 255, 0.14);n      font-size: 12px;n      font-weight: 800;n      letter-spacing: 0.12em;n      text-transform: uppercase;n    }n    .fisica-docentes-hero h1 {n      margin: 16px 0 12px;n      max-width: 14ch;n      font-size: clamp(30px, 4.3vw, 50px);n      line-height: 1.02;n      font-weight: 800;n      color: #ffffff;n    }n    .fisica-docentes-hero p {n      max-width: 74ch;n      margin: 0;n      color: rgba(255, 255, 255, 0.88);n      font-size: 16px;n      line-height: 1.75;n    }n    .fisica-docentes-overview {n      display: grid;n      grid-template-columns: minmax(0, 1.8fr) repeat(3, minmax(0, 1fr));n      gap: 18px;n      margin-bottom: 24px;n    }n    .fisica-docentes-overview__card {n      padding: 22px 22px 20px;n      border-radius: 24px;n      background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);n      border: 1px solid var(--fisica-doc-border);n      box-shadow: var(--fisica-doc-shadow-soft);n    }n    .fisica-docentes-overview__card strong {n      display: block;n      color: var(--fisica-doc-primary-strong);n      font-size: clamp(30px, 4vw, 42px);n      line-height: 1;n      font-weight: 800;n    }n    .fisica-docentes-overview__card span {n      display: block;n      margin-top: 8px;n      color: var(--fisica-doc-text-soft);n      font-size: 14px;n      line-height: 1.6;n    }n    .fisica-docentes-overview__card--lead {n      background:n        linear-gradient(180deg, rgba(255, 255, 255, 0.98) 0%, rgba(237, 245, 255, 0.96) 100%);n    }n    .fisica-docentes-overview__card--lead h2 {n      margin: 0 0 10px;n      color: var(--fisica-doc-primary-strong);n      font-size: clamp(22px, 2.6vw, 30px);n      line-height: 1.15;n      font-weight: 800;n    }n    .fisica-docentes-overview__card--lead p {n      margin: 0;n      color: var(--fisica-doc-text-soft);n      font-size: 15px;n      line-height: 1.7;n    }n    .fisica-docentes-toolbar {n      display: flex;n      flex-wrap: wrap;n      align-items: center;n      justify-content: space-between;n      gap: 16px;n      margin-bottom: 18px;n    }n    .fisica-docentes-search {n      display: flex;n      align-items: center;n      gap: 12px;n      min-width: min(100%, 460px);n      padding: 14px 18px;n      border-radius: 18px;n      background: #ffffff;n      border: 1px solid var(--fisica-doc-border);n      box-shadow: var(--fisica-doc-shadow-soft);n    }n    .fisica-docentes-search span {n      color: var(--fisica-doc-primary);n      font-size: 16px;n      font-weight: 700;n    }n    .fisica-docentes-search input {n      flex: 1 1 auto;n      min-width: 0;n      border: 0;n      outline: none;n      background: transparent;n      color: var(--fisica-doc-primary-strong);n      font-size: 15px;n    }n    .fisica-docentes-search input::placeholder {n      color: #7b90a4;n    }n    .fisica-docentes-toolbar__info {n      color: var(--fisica-doc-text-soft);n      font-size: 14px;n      line-height: 1.6;n    }n    .fisica-docentes-tabs {n      display: flex;n      flex-wrap: wrap;n      gap: 12px;n      margin-bottom: 20px;n    }n    .fisica-docentes-tab {n      display: inline-flex;n      align-items: center;n      gap: 12px;n      appearance: none;n      border: 1px solid rgba(15, 76, 129, 0.16);n      background: #ffffff;n      color: var(--fisica-doc-primary);n      border-radius: 18px;n      padding: 14px 16px;n      font-size: 14px;n      line-height: 1.3;n      font-weight: 800;n      cursor: pointer;n      box-shadow: var(--fisica-doc-shadow-soft);n      transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease, background 180ms ease, color 180ms ease;n    }n    .fisica-docentes-tab:hover,n    .fisica-docentes-tab:focus-visible {n      transform: translateY(-2px);n      border-color: rgba(15, 76, 129, 0.34);n      outline: none;n    }n    .fisica-docentes-tab.is-active {n      background: linear-gradient(135deg, #0f4c81 0%, #1f6fb4 100%);n      color: #ffffff;n      border-color: #0f4c81;n      box-shadow: 0 20px 34px rgba(15, 76, 129, 0.22);n    }n    .fisica-docentes-tab__label {n      text-align: left;n    }n    .fisica-docentes-tab__count {n      display: inline-flex;n      align-items: center;n      justify-content: center;n      min-width: 32px;n      padding: 4px 9px;n      border-radius: 999px;n      background: rgba(15, 76, 129, 0.08);n      font-size: 12px;n      line-height: 1;n      font-weight: 800;n    }n    .fisica-docentes-tab.is-active .fisica-docentes-tab__count {n      background: rgba(255, 255, 255, 0.18);n    }n    .fisica-docentes-panel {n      display: none;n      border: 1px solid var(--fisica-doc-border);n      border-radius: 28px;n      background: linear-gradient(180deg, #ffffff 0%, #f7fbff 100%);n      box-shadow: var(--fisica-doc-shadow);n      overflow: hidden;n    }n    .fisica-docentes-panel.is-active {n      display: block;n    }n    .fisica-docentes-panel__head {n      display: flex;n      flex-wrap: wrap;n      align-items: flex-end;n      justify-content: space-between;n      gap: 18px;n      padding: 24px 24px 18px;n      border-bottom: 1px solid rgba(15, 76, 129, 0.08);n      background:n        radial-gradient(circle at top right, rgba(89, 168, 255, 0.18), transparent 28%),n        linear-gradient(180deg, rgba(15, 76, 129, 0.06), rgba(15, 76, 129, 0.02));n    }n    .fisica-docentes-panel__eyebrow {n      display: inline-flex;n      margin-bottom: 10px;n      padding: 7px 12px;n      border-radius: 999px;n      background: rgba(15, 76, 129, 0.08);n      color: var(--fisica-doc-primary);n      font-size: 11px;n      font-weight: 800;n      letter-spacing: 0.12em;n      text-transform: uppercase;n    }n    .fisica-docentes-panel__head h2 {n      margin: 0;n      color: var(--fisica-doc-primary-strong);n      font-size: clamp(24px, 3vw, 34px);n      line-height: 1.1;n      font-weight: 800;n    }n    .fisica-docentes-panel__head p {n      margin: 10px 0 0;n      max-width: 70ch;n      color: var(--fisica-doc-text-soft);n      font-size: 14px;n      line-height: 1.7;n    }n    .fisica-docentes-panel__meta {n      min-width: 150px;n      padding: 14px 16px;n      border-radius: 18px;n      background: rgba(255, 255, 255, 0.8);n      border: 1px solid rgba(15, 76, 129, 0.12);n      text-align: right;n    }n    .fisica-docentes-panel__meta strong {n      display: block;n      color: var(--fisica-doc-primary-strong);n      font-size: 30px;n      line-height: 1;n      font-weight: 800;n    }n    .fisica-docentes-panel__meta span {n      display: block;n      margin-top: 6px;n      color: var(--fisica-doc-text-soft);n      font-size: 13px;n      line-height: 1.5;n    }n    .fisica-docentes-table-wrap {n      width: 100%;n      overflow-x: auto;n      padding: 0 0 4px;n    }n    .fisica-docentes-table {n      width: 100%;n      min-width: 980px;n      border-collapse: separate;n      border-spacing: 0;n      background: #ffffff;n    }n    .fisica-docentes-table thead th {n      position: sticky;n      top: 0;n      z-index: 1;n      padding: 16px 18px;n      background: #eaf3ff;n      color: var(--fisica-doc-primary-strong);n      border-bottom: 1px solid rgba(15, 76, 129, 0.14);n      font-size: 13px;n      letter-spacing: 0.05em;n      text-transform: uppercase;n      text-align: left;n    }n    .fisica-docentes-table tbody tr {n      transition: background 180ms ease;n    }n    .fisica-docentes-table tbody tr:nth-child(even) {n      background: #f9fcff;n    }n    .fisica-docentes-table tbody tr:hover {n      background: #eef5ff;n    }n    .fisica-docentes-table td {n      padding: 18px;n      border-bottom: 1px solid rgba(15, 76, 129, 0.08);n      color: var(--fisica-doc-text);n      font-size: 15px;n      line-height: 1.65;n      vertical-align: top;n      text-align: left;n    }n    .fisica-docentes-table td:first-child {n      min-width: 270px;n      color: var(--fisica-doc-primary-strong);n      font-weight: 800;n    }n    .fisica-docentes-table td:nth-child(2) {n      min-width: 390px;n    }n    .fisica-docentes-table td:nth-child(3) {n      min-width: 120px;n      white-space: nowrap;n      font-weight: 700;n      color: var(--fisica-doc-primary);n    }n    .fisica-docentes-table td:nth-child(4) {n      min-width: 140px;n    }n    .fisica-docentes-table a {n      display: inline-flex;n      align-items: center;n      justify-content: center;n      padding: 10px 14px;n      border-radius: 999px;n      background: rgba(15, 76, 129, 0.08);n      color: var(--fisica-doc-primary);n      font-size: 13px;n      font-weight: 800;n      text-decoration: none;n      transition: background 180ms ease, color 180ms ease, transform 180ms ease;n    }n    .fisica-docentes-table a:hover,n    .fisica-docentes-table a:focus-visible {n      background: var(--fisica-doc-primary);n      color: #ffffff;n      transform: translateY(-1px);n      outline: none;n    }n    .fisica-docentes-empty-link {n      color: #7a8fa3;n      font-size: 13px;n      font-weight: 700;n    }n    .fisica-docentes-empty {n      padding: 18px 24px 24px;n      color: var(--fisica-doc-text-soft);n      font-size: 14px;n      line-height: 1.6;n    }n    @media (max-width: 1100px) {n      .fisica-docentes-overview {n        grid-template-columns: repeat(2, minmax(0, 1fr));n      }n      .fisica-docentes-overview__card--lead {n        grid-column: 1 / -1;n      }n    }n    @media (max-width: 767px) {n      .fisica-docentes-page {n        padding: 18px 12px 42px;n      }n      .fisica-docentes-hero,n      .fisica-docentes-overview__card,n      .fisica-docentes-panel__head {n        border-radius: 22px;n      }n      .fisica-docentes-overview {n        grid-template-columns: 1fr;n      }n      .fisica-docentes-toolbar {n        align-items: stretch;n      }n      .fisica-docentes-search {n        min-width: 0;n        width: 100%;n      }n      .fisica-docentes-tabs {n        display: grid;n        grid-template-columns: 1fr;n      }n      .fisica-docentes-tab {n        width: 100%;n        justify-content: space-between;n      }n      .fisica-docentes-panel__head {n        padding: 20px 18px 16px;n      }n      .fisica-docentes-panel__meta {n        width: 100%;n        text-align: left;n      }n      .fisica-docentes-table,n      .fisica-docentes-table thead,n      .fisica-docentes-table tbody,n      .fisica-docentes-table tr,n      .fisica-docentes-table td {n        display: block;n        min-width: 0;n        width: 100%;n      }n      .fisica-docentes-table {n        min-width: 0;n        background: transparent;n      }n      .fisica-docentes-table thead {n        display: none;n      }n      .fisica-docentes-table tbody {n        padding: 14px;n      }n      .fisica-docentes-table tbody tr {n        margin-bottom: 14px;n        border: 1px solid rgba(15, 76, 129, 0.12);n        border-radius: 18px;n        background: #ffffff;n        overflow: hidden;n        box-shadow: 0 10px 22px rgba(11, 47, 74, 0.06);n      }n      .fisica-docentes-table td {n        padding: 12px 14px;n        border-bottom: 1px solid rgba(15, 76, 129, 0.08);n        font-size: 14px;n      }n      .fisica-docentes-table td:last-child {n        border-bottom: 0;n      }n      .fisica-docentes-table td::before {n        content: attr(data-label);n        display: block;n        margin-bottom: 6px;n        color: var(--fisica-doc-primary);n        font-size: 11px;n        font-weight: 800;n        letter-spacing: 0.08em;n        text-transform: uppercase;n      }n    }n  </style>nn  <header class=\"fisica-docentes-hero\">n    <span class=\"fisica-docentes-eyebrow\">Instituto de F&iacute;sica UERJ</span>n    <h1>Corpo Docente</h1>n    <!--<p>A p&aacute;gina foi reorganizada para uma leitura mais profissional e atual, mantendo a linguagem visual do site e retomando a rela&ccedil;&atilde;o anterior de professores por &aacute;rea.</p>-->n  </header>nn  <section class=\"fisica-docentes-overview\" aria-label=\"Resumo do corpo docente\">n    <article class=\"fisica-docentes-overview__card fisica-docentes-overview__card--lead\">n      <!--<h2>Consulta mais clara para alunos, visitantes e comunidade acad&ecirc;mica</h2>-->n      <p>Use as abas para navegar pelas &aacute;reas, ou pesquise por nome, tema de pesquisa ou sala. A rela&ccedil;&atilde;o abaixo preserva os docentes anteriormente listados na p&aacute;gina.</p>n    </article>n    <article class=\"fisica-docentes-overview__card\">n      <strong>81</strong>n      <span>docentes distribu&iacute;dos nas &aacute;reas apresentadas nesta p&aacute;gina.</span>n    </article>n    <article class=\"fisica-docentes-overview__card\">n      <strong>4</strong>n      <span>grupos organizados por departamento e &aacute;rea de atua&ccedil;&atilde;o.</span>n    </article>n    <article class=\"fisica-docentes-overview__card\">n      <strong>Lattes</strong>n      <span>acesso direto ao curr&iacute;culo quando informado na rela&ccedil;&atilde;o original.</span>n    </article>n  </section>nn  <div class=\"fisica-docentes-toolbar\">n    <label class=\"fisica-docentes-search\">n      <span>Buscar</span>n      <input type=\"search\" placeholder=\"Digite nome, &aacute;rea de pesquisa ou sala\" data-docentes-search>n    </label>n    <div class=\"fisica-docentes-toolbar__info\" data-docentes-feedback>n      Consulte a rela&ccedil;&atilde;o completa de docentes por &aacute;rea.n    </div>n  </div>nn  <div class=\"fisica-docentes-tabs\" role=\"tablist\" aria-label=\"&Aacute;reas do corpo docente\">n    <button class=\"fisica-docentes-tab is-active\" id=\"fisica-docentes-tab-0\" type=\"button\" role=\"tab\" aria-selected=\"true\" aria-controls=\"fisica-docentes-panel-0\" data-docentes-tab=\"0\"><span class=\"fisica-docentes-tab__label\">Fisica Aplicada e Termodin&acirc;mica</span><span class=\"fisica-docentes-tab__count\">18</span></button><button class=\"fisica-docentes-tab\" id=\"fisica-docentes-tab-1\" type=\"button\" role=\"tab\" aria-selected=\"false\" aria-controls=\"fisica-docentes-panel-1\" data-docentes-tab=\"1\"><span class=\"fisica-docentes-tab__label\">Eletr&ocirc;nica Qu&acirc;ntica</span><span class=\"fisica-docentes-tab__count\">20</span></button><button class=\"fisica-docentes-tab\" id=\"fisica-docentes-tab-2\" type=\"button\" role=\"tab\" aria-selected=\"false\" aria-controls=\"fisica-docentes-panel-2\" data-docentes-tab=\"2\"><span class=\"fisica-docentes-tab__label\">F&iacute;sica Te&oacute;rica</span><span class=\"fisica-docentes-tab__count\">18</span></button><button class=\"fisica-docentes-tab\" id=\"fisica-docentes-tab-3\" type=\"button\" role=\"tab\" aria-selected=\"false\" aria-controls=\"fisica-docentes-panel-3\" data-docentes-tab=\"3\"><span class=\"fisica-docentes-tab__label\">F&iacute;sica Nuclear e Altas Energias</span><span class=\"fisica-docentes-tab__count\">18</span></button>n  </div>nn  <div class=\"fisica-docentes-panels\">n    n    <section class=\"fisica-docentes-panel is-active\" id=\"fisica-docentes-panel-0\" role=\"tabpanel\" aria-labelledby=\"fisica-docentes-tab-0\">n      <div class=\"fisica-docentes-panel__head\">n        <div>n          <span class=\"fisica-docentes-panel__eyebrow\">Corpo docente</span>n          <h2>Fisica Aplicada e Termodin&acirc;mica</h2>n          <p></p>n        </div>n        <div class=\"fisica-docentes-panel__meta\">n          <strong>18</strong>n          <span>docentes nesta &aacute;rea</span>n        </div>n      </div>nn      <div cl