4;\n    }\n    .carousel {\n      position: relative;\n      width: 100%;\n      height: 500px; /* 🔹 Ajuste a altura aqui */\n      overflow: hidden;\n    }\n    .carousel-track {\n      display: flex;\n      transition: transform 0.5s ease-in-out;\n      height: 100%;\n    }\n    .carousel-slide {\n      min-width: 100%;\n      height: 100%;\n      background-size: cover;      /* 🔹 Preenche sempre todo o container */\n      background-position: center; /* 🔹 Centraliza */\n      background-repeat: no-repeat;/* 🔹 Evita repetição */\n    }\n    /* 🔹 Botões de navegação */\n    .carousel-button {\n      position: absolute;\n      top: 50%;\n      transform: translateY(-50%);\n      background: rgba(0,0,0,0.5);\n      border: none;\n      color: #fff;\n      font-size: 2rem;\n      padding: 0.5rem 1rem;\n      cursor: pointer;\n      border-radius: 50%;\n      z-index: 10;\n      transition: background 0.3s;\n    }\n    .carousel-button:hover {\n      background: rgba(0,0,0,0.8);\n    }\n    .carousel-button.prev { left: 20px; }\n    .carousel-button.next { right: 20px; }\n    /* 🔹 Bolinhas indicadores */\n    .carousel-dots {\n      position: absolute;\n      bottom: 15px;\n      left: 50%;\n      transform: translateX(-50%);\n      display: flex;\n      gap: 10px;\n    }\n    .carousel-dot {\n      width: 12px;\n      height: 12px;\n      background: rgba(255,255,255,0.6);\n      border-radius: 50%;\n      cursor: pointer;\n      transition: all 0.3s;\n    }\n    .carousel-dot.active {\n      background: #0072CE;\n      transform: scale(1.3); /* 🔹 Bolinha ativa maior */\n    }\n  \n\n\n    <!-- Botões -->\n    <button>&#10094;</button>\n    <button>&#10095;</button>\n    <!-- Bolinhas -->\n\n\n					<h1>Eventos</h1>																<a href=\"http://localhost/fisica/wp-content/uploads/2025/09/WhatsApp-Image-2025-08-25-at-15.23.48.jpg\">\n							<img width=\"800\" height=\"800\" src=\"http://localhost/fisica/wp-content/uploads/2025/09/WhatsApp-Image-2025-08-25-at-15.23.48